from pathlib import Path
p=Path('frontline.js');s=p.read_text(encoding='utf-8').replace('run?.time||visualTime*.15','run?run.time:0');p.write_text(s,encoding='utf-8')
p=Path('tests/frontline.test.cjs');s=p.read_text(encoding='utf-8').replace('shootAt(370)*2','shootAt(370)');s=s.replace("for(let i=0;i<12;i++)r.unit('walker',326,350);advance(r,4)","for(let i=0;i<12;i++)r.unit('walker',326,200);advance(r,8)")
s+='''
test('all support calls have explicit arrivals and no combat effects before landing',()=>{for(const type of Object.keys(F.ITEMS)){const r=empty();r.inventory=[{type,count:1}];const z=r.unit('armored',200,300,{hp:10000,max:10000,speed:0});assert.ok(r.deploy(0,200,300));const e=r.effects[0];assert.ok([1,2,3].includes(e.arrival));advance(r,e.arrival-.1);assert.equal(z.hp,10000,type);assert.equal(e.detonated,false,type);if(e.ammo)assert.equal(e.ammo,type==='mgTank'?180:28);assert.ok(r.effects.includes(e));advance(r,.2);assert.ok(r.drain().some(v=>v.type==='arrival'&&v.item===type));}});
test('pending shields and vehicles do not absorb attacks',()=>{for(const type of ['energyShield','mgTank','grenadeTank']){const r=empty();r.inventory=[{type,count:1}];r.deploy(0,106,300);r.casualty(2,{y:600,cd:0});assert.equal(r.army,6);}});
test('boss enters with the existing horde and keeps calling reinforcements',()=>{const r=empty();r.stageId=1;r.time=15.99;const z=r.unit('walker',326,200,{speed:0});r.step(.02);assert.ok(r.entities.includes(z));assert.ok(r.entities.some(o=>o.type==='giant'));assert.ok(r.entities.filter(o=>F.TYPES[o.type]&&o.type!=='giant').length>=11);const n=r.entities.length;r.nextWave=r.time;advance(r,.02);assert.ok(r.entities.length>=n+8);});
test('boss strikes apply their configured damage to every soldier inside the footprint',()=>{const r=empty();r.inventory=[{type:'energyShield',count:1}];r.deploy(0,106,300);advance(r,1.1);r.strike(r.x,90,.01,4);advance(r,.02);assert.equal(r.effects.find(e=>e.type==='energyShield').hp,0);});
''';p.write_text(s,encoding='utf-8')
